    # left-side frame on the same row band; color the bitmap's marked cells.
    h,w=len(grid),len(grid[0])
    tops=[0,4,8,12]
    out=[row[:5] for row in grid]
    colors=[]
    for row in grid:
        for v in row[6:]:
            if v and v not in colors: colors.append(v)
    # Objects' vertical centers select their matching frame bands.
    for top in tops:
        bottom=min(top+4,h)
        candidates=[]
        for color in colors:
            cells=[(r,c) for r in range(h) for c in range(6,w) if grid[r][c]==color]
            center=sum(r for r,c in cells)/len(cells)
            candidates.append((abs(center-(top+2)),color))
        color=min(candidates)[1]
        for r in range(top+1,bottom):
            for c in range(1,4):
                if grid[r][c]!=0: out[r][c]=color
    return out
