    # Produce only the transformed left panel. In each framed pattern, the
    # nonzero cells indicate the shape mask. Recolor the mask by the right-side
    # object that is geometrically most similar after translation/rotation/reflection.
    tops=[0,4,8,12]
    masks=[]
    for top in tops:
        masks.append({(r-top-1,c-1) for r in range(top+1,min(top+4,h)) for c in range(1,4) if grid[r][c]!=0})
    colors=[]
