        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        shapes[color]={(r-r0,c-c0) for r,c in cells}
    def transforms(s):
        out=[]
        for flip in [False,True]:
            for k in range(4):
                pts={(r, -c if flip else c) for r,c in s}
                for _ in range(k): pts={(c,-r) for r,c in pts}
                if pts:
                    mr=min(r for r,c in pts); mc=min(c for r,c in pts)
                    out.append({(r-mr,c-mc) for r,c in pts})
        return out
