        if best is None or score>best[0]: best=(score,perm)
    out=[row[:5] for row in grid]
    for i,top in enumerate(tops):
        col=colors[best[1][i]]
        for dr,dc in masks[i]: out[top+1+dr][dc+1]=col
    return out
